    exps := d.OrderBy.Parse()
    for i := range exps {
        // db.Statement.AddClause 是sink
        db.Statement.AddClause(exps[i])
    }

    if exps == nil {
        db.Order("id desc")
    }

    db = db.Offset(d.Pagination.Offset).Limit(d.Pagination.Limit)
    fexp := d.Filter.Parse()
    if fexp != nil {
        db.Statement.AddClause(clause.Where{Exprs: fexp})
    }

    return db.Debug()
}

